pub(super) fn analysis__flaky_classification__normalize_flaky_config(
    mut raw_config: Value,
) -> Result<Value> {
    let mut attempt_history: Value;
    let mut config: Value;
    let mut environment_evidence: Value;
    let mut flake_classes: Value;
    config = builtin(
        "dict",
        &[{
            let first = raw_config.clone();
            if truth(&first) { first } else { json!({}) }
        }],
    )?;
    flake_classes = {
        let mut collected_values = Vec::new();
        for current in sequence(&get(&config, &json!("flake_classes"), Value::Array(vec![])))? {
            let mut fc = current;
            if !(fc.clone().is_object()) {
                continue;
            }
            collected_values.push(analysis__flaky_classification__normalize_flake_class(
                fc.clone(),
            )?);
        }
        Value::Array(collected_values)
    };
    attempt_history = {
        let mut collected_values = Vec::new();
        for current in sequence(&get(
            &config,
            &json!("attempt_history"),
            Value::Array(vec![]),
        ))? {
            let mut attempt = current;
            if !(attempt.clone().is_object()) {
                continue;
            }
            collected_values.push(analysis__flaky_classification__normalize_attempt(
                attempt.clone(),
            )?);
        }
        Value::Array(collected_values)
    };
    environment_evidence = {
        let mut collected_values = Vec::new();
        for current in sequence(&get(
            &config,
            &json!("environment_evidence"),
            Value::Array(vec![]),
        ))? {
            let mut ee = current;
            if !(ee.clone().is_object()) {
                continue;
            }
            collected_values.push(analysis__flaky_classification__normalize_env_evidence(
                ee.clone(),
            )?);
        }
        Value::Array(collected_values)
    };
    return Ok(Value::Object(
        [
            ("flake_classes".into(), flake_classes.clone()),
            ("attempt_history".into(), attempt_history.clone()),
            ("environment_evidence".into(), environment_evidence.clone()),
            (
                "analysis_scope".into(),
                json!(values::text(&{
                    let first = get(&config, &json!("analysis_scope"), json!(""));
                    if truth(&first) { first } else { json!("") }
                })),
            ),
            ("input_refs".into(), {
                let mut collected_values = Vec::new();
                for current in sequence(&get(&config, &json!("input_refs"), Value::Array(vec![])))?
                {
                    let mut r#ref = current;
                    if !(truth(&json!(values::text(&r#ref)))) {
                        continue;
                    }
                    collected_values.push(json!(values::text(&r#ref)));
                }
                Value::Array(collected_values)
            }),
            (
                "confidence".into(),
                json!(number(&{
                    let first = get(&config, &json!("confidence"), json!(0.0));
                    if truth(&first) { first } else { json!(0.0) }
                })?),
            ),
            (
                "limits".into(),
                analysis__flaky_classification__normalize_limits(get(
                    &config,
                    &json!("limits"),
                    json!({}),
                ))?,
            ),
            (
                "class_taxonomy_available".into(),
                json!(truth(&get(
                    &config,
                    &json!("class_taxonomy_available"),
                    json!(false)
                ))),
            ),
            (
                "retry_history_available".into(),
                json!(truth(&get(
                    &config,
                    &json!("retry_history_available"),
                    json!(false)
                ))),
            ),
            (
                "environment_evidence_available".into(),
                json!(truth(&get(
                    &config,
                    &json!("environment_evidence_available"),
                    json!(false)
                ))),
            ),
        ]
        .into_iter()
        .collect(),
    ));
}

